document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("shoe-size-form"),s=document.getElementById("unit"),n=document.getElementById("value"),a=document.getElementById("shoe-size-result");s.addEventListener("change",()=>{switch(s.value){case"mondopoint":n.placeholder="e.g., 270";break;case"eu":n.placeholder="e.g., 42";break;case"uk":n.placeholder="e.g., 8";break;case"us_m":n.placeholder="e.g., 9";break;case"us_w":n.placeholder="e.g., 10.5"}}),e.addEventListener("submit",e=>{e.preventDefault(),a.textContent="";const i=s.value,t=parseFloat(n.value.replace(",","."));if(isNaN(t)||t<=0)return a.innerHTML="<p>Please enter a valid value.</p>",void 0;let o,l,r,c,d;"mondopoint"===i?o=t:"eu"===i?(l=t,o=6.67*l-10):"uk"===i?o=25.5+8.467*t:"us_m"===i?o=24+8.467*t:"us_w"===i&&(o=22.5+8.467*t),"eu"!==i&&"number"==typeof o&&(l=(o+10)/6.67),r=(o-25.5)/8.467,c=(o-24)/8.467,d=(o-22.5)/8.467;const p=e=>e>0?e.toFixed(1):"N/A";a.innerHTML=`\n      <h3>Shoe Size Conversion Results:</h3>\n      <div class="size-conversion-table">\n        <div class="size-row">\n          <span class="size-label">Foot Length (Mondopoint):</span>\n          <span class="size-value">${o.toFixed(0)} mm</span>\n        </div>\n        <div class="size-row">\n          <span class="size-label">European (EU):</span>\n          <span class="size-value">${p(l)}</span>\n        </div>\n        <div class="size-row">\n          <span class="size-label">UK Size:</span>\n          <span class="size-value">${p(r)}</span>\n        </div>\n        <div class="size-row">\n          <span class="size-label">US Men's:</span>\n          <span class="size-value">${p(c)}</span>\n        </div>\n        <div class="size-row">\n          <span class="size-label">US Women's:</span>\n          <span class="size-value">${p(d)}</span>\n        </div>\n      </div>\n      \n      <div class="conversion-notes">\n        <h4>Important Sizing Notes:</h4>\n        <ul>\n          <li><strong>Half sizes:</strong> If your result falls between whole sizes (e.g., 8.3), you can choose either 8 or 8.5 based on your fit preference</li>\n          <li><strong>Brand variations:</strong> Sizes can vary between brands by up to ½ size, so always check specific brand charts</li>\n          <li><strong>Shoe type:</strong> Athletic shoes often run larger than dress shoes in the same size</li>\n          <li><strong>Width consideration:</strong> This converter focuses on length; consider width fittings (narrow, medium, wide) separately</li>\n          <li><strong>Best practice:</strong> When shopping online, read customer reviews about sizing and fit</li>\n        </ul>\n      </div>\n      \n      <div class="measurement-tip">\n        <h4>Pro Tip:</h4>\n        <p>Your foot length is <strong>${o.toFixed(0)}mm</strong>. When shopping online, look for brands that provide foot length measurements in their size charts for the most accurate fit.</p>\n      </div>\n    `})});